import { dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { nested } from "./nested space/child.js";

export function metadata() {
  const file = fileURLToPath(import.meta.url);
  return [
    import.meta.url.startsWith("file://") ? "true" : "false",
    import.meta.url.includes("index.js") ? "true" : "false",
    file.endsWith("/index.js") ? "true" : "false",
    dirname(file).length > 0 ? "true" : "false",
    nested,
  ];
}
